head.b:skin:
/* =========================================================
   ゆすらご ｜ 喫茶店ホームページ
   やわらかい緑 × 昭和レトロ喫茶 × ちょっとレトロPC
   ---------------------------------------------------------
   このファイルがデザインの唯一の出典です。
   色や余白を変えたいときはまず :root の変数をいじってください。
   ========================================================= */

/* ---------- 1. トークン ---------- */
:root{
  /* 緑（やわらかめ） */
  --deep:#22331f;
  --moss:#4c6b48;
  --leaf:#6f9163;
  --sage:#9db894;
  --pale:#d9e3cd;
  /* 紙 */
  --cream:#f4efdf;
  --paper:#fcf9f0;
  /* 墨 */
  --ink:#2c332a;
  --ink-soft:#5d6757;
  /* さし色 */
  --amber:#d69a45;      /* プリン */
  --vermilion:#b95440;  /* ナポリタン */
  --soda:#4fa39a;       /* クリームソーダ */

  --bg:var(--cream);
  --surface:var(--paper);
  --text:var(--ink);
  --muted:var(--ink-soft);
  --frame:var(--deep);
  --line:rgba(34,51,31,.18);
  --bar-a:var(--moss);
  --bar-b:var(--leaf);
  --bar-text:#f4efdf;
  --shadow-color:var(--sage);

  --mincho:"Shippori Mincho B1","Hiragino Mincho ProN","Yu Mincho",serif;
  --gothic:"Zen Kaku Gothic New","Hiragino Sans","Yu Gothic",sans-serif;
  --dot:"DotGothic16","Hiragino Sans",monospace;

  --maxw:1060px;
  --gutter:16px;
}

@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#161e15;
    --surface:#1e2a1c;
    --text:#e6ecdd;
    --muted:#a9b9a2;
    --frame:#86a67c;
    --line:rgba(230,236,221,.22);
    --pale:#2c3b28;
    --bar-a:#2f4a2c;
    --bar-b:#3e5c39;
    --shadow-color:#33492f;
  }
}
:root[data-theme="dark"]{
  --bg:#161e15;
  --surface:#1e2a1c;
  --text:#e6ecdd;
  --muted:#a9b9a2;
  --frame:#86a67c;
  --line:rgba(230,236,221,.22);
  --pale:#2c3b28;
  --bar-a:#2f4a2c;
  --bar-b:#3e5c39;
  --shadow-color:#33492f;
}

/* ---------- 2. 土台 ---------- */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background-color:var(--bg);
  /* 方眼紙のようなうっすらした地紋 */
  background-image:
    linear-gradient(var(--line) 1px,transparent 1px),
    linear-gradient(90deg,var(--line) 1px,transparent 1px);
  background-size:28px 28px,28px 28px;
  background-position:-1px -1px,-1px -1px;
  color:var(--text);
  font-family:var(--gothic);
  font-size:16px;
  line-height:1.9;
  letter-spacing:.04em;
}
img{max-width:100%;height:auto;display:block}
a{color:inherit}
h1,h2,h3{font-family:var(--mincho);font-weight:700;line-height:1.45;letter-spacing:.08em;margin:0}
p{margin:0 0 1em}
ul{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--gutter)}
.skip{position:absolute;left:-9999px}
.skip:focus{left:8px;top:8px;z-index:99;background:var(--surface);border:2px solid var(--frame);padding:.5em 1em}
:where(a,button):focus-visible{outline:3px solid var(--amber);outline-offset:2px}

/* ---------- 3. ヘッダー ---------- */
.site-header{
  position:sticky;top:0;z-index:20;
  background:var(--surface);
  border-bottom:2px solid var(--frame);
  box-shadow:0 2px 0 var(--shadow-color);
}
.site-header__inner{
  display:flex;align-items:center;justify-content:space-between;
  gap:1em;min-height:60px;
}
.logo{display:flex;align-items:center;gap:.6em;text-decoration:none}
.logo__mark{width:30px;height:30px;flex:none}
.logo__name{font-family:var(--mincho);font-size:1.25rem;letter-spacing:.18em}
.logo__roma{font-family:var(--dot);font-size:.68rem;color:var(--muted);letter-spacing:.18em;display:block;line-height:1}

.nav{overflow-x:auto;scrollbar-width:none}
.nav::-webkit-scrollbar{display:none}
.nav ul{display:flex;gap:.2em;white-space:nowrap}
.nav a{
  display:block;text-decoration:none;
  font-family:var(--dot);font-size:.9rem;letter-spacing:.1em;
  padding:.45em .7em;border:1px solid transparent;
}
.nav a:hover,.nav a:focus-visible{border-color:var(--frame);background:var(--pale)}

/* ---------- 4. ヒーロー ---------- */
.hero{
  position:relative;overflow:hidden;
  border-bottom:2px solid var(--frame);
  background:
    radial-gradient(120% 90% at 20% 0%,rgba(157,184,148,.55),transparent 60%),
    linear-gradient(160deg,var(--moss),var(--deep));
  color:#f4efdf;
}
/* ブラウン管のような走査線 */
.hero::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(rgba(0,0,0,.14) 0 1px,transparent 1px 4px);
  mix-blend-mode:multiply;opacity:.5;
}
.hero__inner{
  position:relative;z-index:1;
  display:grid;grid-template-columns:1fr auto;align-items:center;gap:2em;
  padding-block:clamp(48px,9vw,96px);
}
.hero__eyebrow{
  font-family:var(--dot);font-size:.8rem;letter-spacing:.22em;
  color:var(--pale);margin:0 0 1.2em;
}
.hero__title{
  font-size:clamp(2.6rem,9vw,4.4rem);letter-spacing:.16em;margin:0 0 .3em;
  text-shadow:3px 3px 0 rgba(34,51,31,.45);
}
.hero__sub{font-family:var(--dot);font-size:.95rem;letter-spacing:.18em;color:var(--pale);margin:0 0 1.4em}
.hero__lead{font-size:1.02rem;max-width:26em;margin:0 0 1.8em;color:#eef0e2}
.cursor{display:inline-block;width:.6em;background:currentColor;color:var(--amber);animation:blink 1.1s steps(1,end) infinite}
@keyframes blink{50%{opacity:0}}
.hero__cta{display:flex;flex-wrap:wrap;gap:.7em}
.hero__art{width:clamp(110px,20vw,180px);height:auto;filter:drop-shadow(4px 4px 0 rgba(34,51,31,.4))}

.btn{
  display:inline-block;text-decoration:none;
  font-family:var(--dot);letter-spacing:.12em;font-size:.92rem;
  padding:.65em 1.3em;border:2px solid var(--deep);
  background:var(--cream);color:var(--deep);
  box-shadow:4px 4px 0 var(--deep);
  transition:transform .08s ease,box-shadow .08s ease;
}
.btn:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--deep)}
.btn:active{transform:translate(4px,4px);box-shadow:0 0 0 var(--deep)}
.btn--ghost{background:transparent;color:#f4efdf;border-color:#f4efdf;box-shadow:4px 4px 0 rgba(34,51,31,.5)}

/* ---------- 5. お知らせ帯 ---------- */
.notice{
  background:var(--pale);border-bottom:2px solid var(--frame);
  font-family:var(--dot);font-size:.88rem;letter-spacing:.08em;
}
.notice__inner{display:flex;gap:1em;align-items:baseline;padding-block:.6em;flex-wrap:wrap}
.notice__tag{
  flex:none;background:var(--vermilion);color:#fff;
  padding:.1em .7em;letter-spacing:.14em;
}
.notice ul{display:flex;flex-direction:column;gap:.2em}
.notice li::before{content:"▼ ";color:var(--moss)}

/* ---------- 6. セクション共通 ---------- */
.section{padding-block:clamp(48px,8vw,88px)}
.section--tint{background:linear-gradient(var(--pale),transparent)}
.section__head{margin:0 0 2.2em;text-align:center}
.section__label{
  display:block;font-family:var(--dot);font-size:.78rem;
  letter-spacing:.3em;color:var(--moss);margin-bottom:.5em;
}
.section__title{font-size:clamp(1.6rem,4.5vw,2.2rem);letter-spacing:.2em}
.section__title::after{
  content:"";display:block;width:56px;height:3px;margin:.6em auto 0;
  background:repeating-linear-gradient(90deg,var(--moss) 0 6px,transparent 6px 10px);
}

/* ---------- 7. レトロPC風ウィンドウ ---------- */
.win{
  background:var(--surface);
  border:2px solid var(--frame);
  box-shadow:6px 6px 0 var(--shadow-color);
}
.win__bar{
  display:flex;align-items:center;gap:.6em;
  padding:.35em .7em;
  background:linear-gradient(90deg,var(--bar-a),var(--bar-b));
  color:var(--bar-text);
  border-bottom:2px solid var(--frame);
  font-family:var(--dot);font-size:.82rem;letter-spacing:.14em;
}
.win__dots{display:flex;gap:4px;margin-left:auto}
.win__dots i{width:10px;height:10px;border:1px solid var(--bar-text);display:block}
.win__body{padding:clamp(20px,4vw,36px)}

/* ---------- 8. 店のこと ---------- */
.about{display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(24px,5vw,48px);align-items:start}
.about__text p:last-child{margin-bottom:0}
.about__name{font-family:var(--mincho);font-size:1.3rem;letter-spacing:.16em;margin-bottom:.8em}
.memo{
  border:2px dashed var(--moss);background:var(--surface);
  padding:1.2em 1.4em;font-size:.93rem;
}
.memo__title{font-family:var(--dot);font-size:.84rem;letter-spacing:.14em;color:var(--moss);margin-bottom:.5em}
.memo p:last-child{margin-bottom:0}

/* ---------- 9. お品書き ---------- */
.menu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(20px,4vw,40px)}
.menu-block+.menu-block{margin-top:2em}
.menu-block__title{
  font-family:var(--mincho);font-size:1.12rem;letter-spacing:.16em;
  padding-bottom:.3em;margin-bottom:.8em;
  border-bottom:2px solid var(--frame);
}
.menu-block__title span{font-family:var(--dot);font-size:.7rem;letter-spacing:.2em;color:var(--muted);margin-left:.8em}
.menu-row{display:flex;align-items:baseline;gap:.5em;padding:.3em 0}
.menu-row__name{font-size:1rem}
.menu-row__note{display:block;font-size:.8rem;color:var(--muted);line-height:1.6}
.menu-row__lead{flex:1 1 auto;min-width:1.5em;border-bottom:1px dotted var(--line);transform:translateY(-.3em)}
.menu-row__price{flex:none;font-family:var(--dot);font-size:.95rem;letter-spacing:.06em}
.menu-note{margin-top:1.6em;font-size:.85rem;color:var(--muted)}

/* ---------- 10. 店内（写真枠） ---------- */
.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.frame{
  position:relative;aspect-ratio:4/3;overflow:hidden;
  border:2px solid var(--frame);background:var(--pale);
  box-shadow:4px 4px 0 var(--shadow-color);
}
.frame img{width:100%;height:100%;object-fit:cover}
/* 写真がまだ無いとき用の市松模様プレースホルダ */
.frame--empty{
  display:grid;place-items:center;
  background-image:
    linear-gradient(45deg,var(--sage) 25%,transparent 25%,transparent 75%,var(--sage) 75%),
    linear-gradient(45deg,var(--sage) 25%,transparent 25%,transparent 75%,var(--sage) 75%);
  background-size:20px 20px;background-position:0 0,10px 10px;
  opacity:.75;
}
.frame--empty span{
  font-family:var(--dot);font-size:.78rem;letter-spacing:.14em;
  background:var(--surface);border:1px solid var(--frame);padding:.3em .8em;
}
.frame__cap{
  position:absolute;left:0;right:0;bottom:0;
  font-family:var(--dot);font-size:.72rem;letter-spacing:.12em;
  background:rgba(34,51,31,.82);color:#f4efdf;padding:.3em .6em;
}

/* ---------- 11. 営業案内 ---------- */
.info{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,5vw,44px)}
.hours{width:100%;border-collapse:collapse;font-size:.95rem}
.hours caption{
  font-family:var(--dot);font-size:.8rem;letter-spacing:.2em;
  color:var(--moss);text-align:left;padding-bottom:.6em;
}
.hours th,.hours td{border:1px solid var(--line);padding:.55em .8em;text-align:left}
.hours th{background:var(--pale);font-weight:500;width:7.5em;font-family:var(--dot);font-size:.86rem;letter-spacing:.1em}
.hours td{font-family:var(--dot);font-size:.9rem}
.hours .is-closed{color:var(--vermilion)}

.dl{margin:0;font-size:.95rem}
.dl div{display:grid;grid-template-columns:6.5em 1fr;gap:.6em;padding:.5em 0;border-bottom:1px dotted var(--line)}
.dl dt{font-family:var(--dot);font-size:.84rem;letter-spacing:.1em;color:var(--moss)}
.dl dd{margin:0}
.map{margin-top:1.4em;border:2px solid var(--frame);box-shadow:4px 4px 0 var(--shadow-color)}
.map iframe{display:block;width:100%;height:280px;border:0}

/* ---------- 12. 日記（ブログ） ---------- */
.posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.post{
  display:flex;flex-direction:column;gap:.4em;
  text-decoration:none;background:var(--surface);
  border:2px solid var(--frame);padding:1.1em 1.2em;
  box-shadow:4px 4px 0 var(--shadow-color);
  transition:transform .08s ease,box-shadow .08s ease;
}
.post:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--shadow-color)}
.post__date{font-family:var(--dot);font-size:.76rem;letter-spacing:.14em;color:var(--moss)}
.post__title{font-family:var(--mincho);font-size:1.02rem;letter-spacing:.06em;line-height:1.65}
.post__more{font-family:var(--dot);font-size:.76rem;color:var(--muted);margin-top:auto}
.center{text-align:center;margin-top:2.2em}

/* ---------- 13. フッター ---------- */
.site-footer{
  border-top:2px solid var(--frame);
  background:linear-gradient(160deg,var(--moss),var(--deep));
  color:#e9eedd;padding-block:40px 28px;margin-top:0;
}
.footer__grid{display:grid;grid-template-columns:1.2fr .8fr;gap:2em;align-items:start}
.footer__name{font-family:var(--mincho);font-size:1.4rem;letter-spacing:.2em;margin-bottom:.2em}
.footer__roma{font-family:var(--dot);font-size:.72rem;letter-spacing:.24em;color:var(--pale)}
.footer__addr{font-size:.9rem;margin-top:1em;color:#dde5d0}
.sns{display:flex;gap:.6em;margin-top:1.2em;flex-wrap:wrap}
.sns a{
  font-family:var(--dot);font-size:.82rem;letter-spacing:.1em;text-decoration:none;
  border:1px solid #e9eedd;padding:.35em .8em;
}
.sns a:hover{background:#e9eedd;color:var(--deep)}
.counter{
  font-family:var(--dot);font-size:.76rem;letter-spacing:.12em;
  border:1px solid rgba(233,238,221,.5);padding:.6em .8em;display:inline-block;
}
.counter b{
  display:inline-block;background:var(--deep);color:var(--amber);
  padding:.1em .4em;letter-spacing:.3em;margin-inline:.3em;
}
.copyright{
  margin-top:2.4em;padding-top:1.2em;border-top:1px dotted rgba(233,238,221,.4);
  font-family:var(--dot);font-size:.72rem;letter-spacing:.1em;color:var(--pale);text-align:center;
}

/* ---------- 14. レスポンシブ ---------- */
@media (max-width:860px){
  .about,.info,.menu-grid,.footer__grid{grid-template-columns:1fr}
  .posts{grid-template-columns:1fr 1fr}
  .hero__inner{grid-template-columns:1fr}
  .hero__art{justify-self:end;margin-top:-1em}
}
@media (max-width:600px){
  .site-header__inner{flex-direction:column;align-items:stretch;gap:.2em;padding-block:.6em}
  .nav ul{justify-content:flex-start}
  .gallery,.posts{grid-template-columns:1fr 1fr}
  .hero__title{letter-spacing:.1em}
}

/* ---------- 15. 配慮 ---------- */
@media (prefers-reduced-motion:reduce){
  *{animation:none !important;transition:none !important}
}
@media print{
  .hero::after,.nav,.site-footer{display:none}
  body{background:#fff}
}


/* ---------- Blogger 記事本文むけの追記 ---------- */
.entry{margin-bottom:2em}
.entry__title{font-size:clamp(1.4rem,4vw,1.9rem);letter-spacing:.12em;margin-bottom:.8em}
.entry__title a{text-decoration:none}
.entry__body{line-height:2.05}
.entry__body img{border:2px solid var(--frame);box-shadow:4px 4px 0 var(--shadow-color);margin:1.4em 0}
.entry__body h2,.entry__body h3{margin:1.8em 0 .6em}
.entry__body a{color:var(--moss)}
.entry__body blockquote{
  margin:1.4em 0;padding:.8em 1.2em;
  border-left:4px solid var(--sage);background:var(--pale);
}
.pager{display:flex;gap:.8em;justify-content:center;flex-wrap:wrap;margin-top:2.4em}
.widget-item-control,.quickedit,.post-feeds,.feed-links{display:none}
